<template><main class="admin-content">
<div class="flex flex-wrap items-end justify-between gap-4"><div><NuxtLink to="/admin/products" class="text-sm font-bold text-blue-600">← Products</NuxtLink><p class="mt-3 text-xs font-black uppercase tracking-wider text-blue-600">Products</p><h1 class="text-3xl font-black">Stocktake</h1><p class="text-slate-500">Create a count snapshot, enter physical counts, review variances and post audited adjustments.</p></div><button v-if="!active" class="btn-primary" :disabled="busy" @click="createStocktake">Start New Stocktake</button></div>
<div v-if="message" class="mt-4 rounded-xl bg-emerald-50 p-3 font-semibold text-emerald-800">{{message}}</div><div v-if="err" class="mt-4 rounded-xl bg-red-50 p-3 font-semibold text-red-700">{{err}}</div>
<section v-if="active" class="panel mt-5 p-4"><div class="flex flex-wrap justify-between gap-3"><div><p class="text-xs font-bold uppercase text-blue-600">{{active.stocktake_number}}</p><h2 class="text-xl font-black">{{active.status==='open'?'Open Stocktake':'Posted Stocktake'}}</h2><p class="text-sm text-slate-500">Expected quantities were frozen when this stocktake was created.</p></div><div class="flex gap-2"><button v-if="active.status==='open'" class="btn-secondary" :disabled="busy" @click="saveCounts">Save Counts</button><button v-if="active.status==='open'" class="btn-primary" :disabled="busy||!allCounted" @click="postStocktake">Post Stocktake</button><button class="btn-secondary" @click="active=null">Close</button></div></div>
<div class="mt-4 grid gap-3 sm:grid-cols-4"><div class="metric"><small>Products</small><b>{{lines.length}}</b></div><div class="metric"><small>Counted</small><b>{{counted}}</b></div><div class="metric"><small>Variances</small><b>{{variances.length}}</b></div><div class="metric"><small>Variance Value</small><b>{{money(varianceValue)}}</b></div></div></section>
<section v-if="active" class="panel mt-5 p-4"><input v-model="search" class="input w-full" placeholder="Search product or SKU…"></section>
<section v-if="active" class="panel mt-5 overflow-hidden"><div class="overflow-x-auto"><table class="w-full min-w-[850px] text-sm"><thead><tr class="bg-slate-50 text-left text-xs uppercase text-slate-500"><th class="p-3">Product</th><th>SKU</th><th class="text-right">Expected</th><th class="text-right">Counted</th><th class="text-right">Variance</th><th class="p-3 text-right">Value</th></tr></thead><tbody><tr v-for="x in shown" :key="x.id" class="border-t"><td class="p-3 font-bold">{{x.products?.name}}</td><td>{{x.products?.product_code||'—'}}</td><td class="text-right">{{x.system_quantity}}</td><td class="text-right"><input v-if="active.status==='open'" v-model.number="x.counted_quantity" type="number" min="0" step="1" class="input w-24 text-right"><span v-else>{{x.counted_quantity}}</span></td><td class="text-right" :class="variance(x)!==0?'font-bold text-amber-700':''">{{variance(x)}}</td><td class="p-3 text-right">{{money(variance(x)*Number(x.unit_cost_ex_gst||0))}}</td></tr></tbody></table></div></section>
<section class="panel mt-5 overflow-hidden"><div class="border-b p-4"><h2 class="text-lg font-black">Stocktake History</h2></div><div class="divide-y"><button v-for="x in history" :key="x.id" class="flex w-full justify-between p-4 text-left hover:bg-slate-50" @click="openStocktake(x.id)"><span><b>{{x.stocktake_number}}</b><span class="ml-2 text-sm text-slate-500">{{date(x.created_at)}}</span></span><span class="rounded-full px-2 py-1 text-xs font-bold" :class="x.status==='posted'?'bg-emerald-100 text-emerald-700':'bg-blue-100 text-blue-700'">{{x.status}}</span></button><div v-if="!history.length" class="p-6 text-center text-slate-500">No stocktakes yet.</div></div></section>
</main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch}=useAdminFetch();const busy=ref(false),err=ref(''),message=ref(''),search=ref(''),active=ref<any>(null),history=ref<any[]>([]);const lines=computed(()=>active.value?.lines||[]);const counted=computed(()=>lines.value.filter((x:any)=>x.counted_quantity!==null&&x.counted_quantity!=='').length);const allCounted=computed(()=>!!lines.value.length&&counted.value===lines.value.length);const variance=(x:any)=>x.counted_quantity===null||x.counted_quantity===''?0:Number(x.counted_quantity)-Number(x.system_quantity||0);const variances=computed(()=>lines.value.filter((x:any)=>variance(x)!==0));const varianceValue=computed(()=>variances.value.reduce((a:number,x:any)=>a+variance(x)*Number(x.unit_cost_ex_gst||0),0));const shown=computed(()=>{const q=search.value.toLowerCase().trim();return lines.value.filter((x:any)=>!q||String(x.products?.name||'').toLowerCase().includes(q)||String(x.products?.product_code||'').toLowerCase().includes(q))});const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));const date=(v:any)=>v?new Date(v).toLocaleString('en-AU'):'—';async function loadHistory(){history.value=await adminFetch('/api/admin/accounting/stocktake/sessions') as any[]||[]}async function openStocktake(id:any){busy.value=true;try{active.value=await adminFetch(`/api/admin/accounting/stocktake/sessions/${id}`)}catch(e:any){err.value=e?.data?.statusMessage||e?.message}finally{busy.value=false}}async function createStocktake(){busy.value=true;err.value='';try{const r:any=await adminFetch('/api/admin/accounting/stocktake/sessions',{method:'POST',body:{}});await openStocktake(r.id);await loadHistory();message.value=`${r.stocktake_number} created with ${r.products} products.`}catch(e:any){err.value=e?.data?.statusMessage||e?.message}finally{busy.value=false}}async function saveCounts(){busy.value=true;try{await adminFetch(`/api/admin/accounting/stocktake/sessions/${active.value.id}/save`,{method:'PUT',body:{lines:lines.value.map((x:any)=>({id:x.id,counted_quantity:x.counted_quantity}))}});message.value='Counts saved.'}catch(e:any){err.value=e?.data?.statusMessage||e?.message}finally{busy.value=false}}async function postStocktake(){if(!confirm(`Post ${active.value.stocktake_number}? This will update live stock and create accounting adjustments.`))return;busy.value=true;try{await saveCounts();const r:any=await adminFetch(`/api/admin/accounting/stocktake/sessions/${active.value.id}/post`,{method:'POST',body:{reason:'Stocktake variance'}});message.value=`${r.stocktake_number} posted. ${r.adjusted} product(s) adjusted.`;await openStocktake(active.value.id);await loadHistory()}catch(e:any){err.value=e?.data?.statusMessage||e?.message}finally{busy.value=false}}onMounted(loadHistory)</script>
<style scoped>.panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.metric{@apply rounded-xl bg-slate-50 p-4}.metric small{@apply block text-xs font-bold uppercase text-slate-500}.metric b{@apply mt-1 block text-2xl}.input{@apply rounded-lg border border-slate-300 bg-white px-3 py-2}.btn-primary{@apply rounded-lg bg-blue-600 px-4 py-2 font-bold text-white hover:bg-blue-700 disabled:opacity-50}.btn-secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 font-bold text-slate-700 hover:bg-slate-50 disabled:opacity-50}</style>
